import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  ActivityIndicator,
  TouchableOpacity,
  TextInput,
  Alert,
  Linking,
} from 'react-native';
import { Image } from 'expo-image';
import * as Clipboard from 'expo-clipboard';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import api from '../services/api';
import { getCustomerBookings, apiErrorMessage, type BookingLink, type MeritBooking } from '../services/bookings';
import {
  getCustomerQuotations,
  createQuotationFromChat,
  sendQuotationToChat,
  shareQuotationLink,
  attachQuotationToCustomer,
  faStatusLabel,
  faStatusStyle,
  originLabel,
  ORIGIN_STYLE,
  type CrmQuotation,
} from '../services/quotations';
import BookingLinkModal from '../components/booking/BookingLinkModal';
import AttachQuotationModal from '../components/booking/AttachQuotationModal';
import { statusLabel, statusStyle } from '../components/booking/bookingHelpers';

export default function CustomerInfoScreen({ route }: any) {
  const { docId, userId, displayName, pictureUrl, channel, channelType } = route.params;
  const insets = useSafeAreaInsets();
  const [details, setDetails] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [editingNickname, setEditingNickname] = useState(false);
  const [nicknameValue, setNicknameValue] = useState('');

  // Notes
  const [notes, setNotes] = useState<any[]>([]);
  const [newNote, setNewNote] = useState('');
  const [addingNote, setAddingNote] = useState(false);

  // Tags
  const [newTag, setNewTag] = useState('');
  const [showTagInput, setShowTagInput] = useState(false);

  // Jobs & Quotations (IRIS Quotation documents attributed to this chat + phone/name matches)
  const [jobs, setJobs] = useState<any[]>([]);
  const [quotations, setQuotations] = useState<CrmQuotation[]>([]);
  const [quotationsLoading, setQuotationsLoading] = useState(false);
  const [showAttachQuote, setShowAttachQuote] = useState(false);
  const [quoteBusy, setQuoteBusy] = useState<string | null>(null); // 'create' | docNo
  const [quoteMsg, setQuoteMsg] = useState<{ ok: boolean; text: string } | null>(null);

  const reloadQuotations = async () => {
    setQuotationsLoading(true);
    try {
      setQuotations(await getCustomerQuotations(docId));
    } catch { /* keep what we have */ } finally {
      setQuotationsLoading(false);
    }
  };

  /** "สร้างใบเสนอราคาทั่วไป": empty draft in IRIS Quotation attributed to this chat + me; opens the editor. */
  const createGeneralQuotation = () => {
    const name = details?.nickname || displayName || 'ลูกค้า';
    Alert.alert(
      'สร้างใบเสนอราคาร่าง',
      `สร้างใบเสนอราคาร่างสำหรับ ${name}?\n\nระบบจะเปิด IRIS Quotation ให้เติมรายการ ใบนี้จะผูกกับแชตนี้และเซลล์ของคุณอัตโนมัติ`,
      [
        { text: 'ยกเลิก', style: 'cancel' },
        {
          text: 'สร้าง',
          onPress: async () => {
            setQuoteBusy('create');
            setQuoteMsg(null);
            try {
              const res = await createQuotationFromChat(docId);
              if (res.editUrl) Linking.openURL(res.editUrl).catch(() => {});
              setQuoteMsg({ ok: true, text: `สร้าง ${res.docNo} แล้ว — เติมรายการใน IRIS Quotation แล้วกลับมากด "ส่งลิงก์เข้าแชต"` });
              await reloadQuotations();
            } catch (e: any) {
              setQuoteMsg({ ok: false, text: apiErrorMessage(e, 'สร้างใบเสนอราคาไม่สำเร็จ') });
            } finally {
              setQuoteBusy(null);
            }
          },
        },
      ],
    );
  };

  const sendQuoteToChat = async (docNo: string) => {
    setQuoteBusy(docNo);
    setQuoteMsg(null);
    try {
      await sendQuotationToChat(docNo);
      setQuoteMsg({ ok: true, text: `ส่งลิงก์ ${docNo} เข้าแชตแล้ว` });
      await reloadQuotations();
    } catch (e: any) {
      setQuoteMsg({ ok: false, text: apiErrorMessage(e, 'ส่งไม่สำเร็จ') });
    } finally {
      setQuoteBusy(null);
    }
  };

  const copyQuoteLink = async (q: CrmQuotation) => {
    try {
      const url = q.publicUrl || (await shareQuotationLink(q.docNo)).publicUrl;
      await Clipboard.setStringAsync(url);
      setQuoteMsg({ ok: true, text: `คัดลอกลิงก์ ${q.docNo} แล้ว` });
      if (!q.publicUrl) await reloadQuotations();
    } catch (e: any) {
      setQuoteMsg({ ok: false, text: apiErrorMessage(e, 'คัดลอกลิงก์ไม่สำเร็จ') });
    }
  };

  const attachQuote = async (docNo: string) => {
    setQuoteBusy(docNo);
    setQuoteMsg(null);
    try {
      await attachQuotationToCustomer(docNo, docId);
      setQuoteMsg({ ok: true, text: `ผูก ${docNo} กับแชตนี้แล้ว` });
      await reloadQuotations();
    } catch (e: any) {
      setQuoteMsg({ ok: false, text: apiErrorMessage(e, 'ผูกไม่สำเร็จ') });
    } finally {
      setQuoteBusy(null);
    }
  };

  // Merit bookings (/booking page) + booking links sent to this customer
  const [bookings, setBookings] = useState<MeritBooking[]>([]);
  const [bookingLinks, setBookingLinks] = useState<BookingLink[]>([]);
  const [showBookingLink, setShowBookingLink] = useState(false);
  const [copiedToken, setCopiedToken] = useState<string | null>(null);

  const refreshBookings = () =>
    getCustomerBookings(docId)
      .then((r) => { setBookings(r.bookings); setBookingLinks(r.links); })
      .catch(() => {});

  useEffect(() => {
    let cancelled = false;
    Promise.all([
      api.get(`/users/${docId}/details`),
      api.get(`/users/${docId}/notes`).catch(() => ({ data: [] })),
      api.get(`/users/${docId}/jobs`).catch(() => ({ data: { jobs: [] } })),
      api.get(`/users/${docId}/quotations`).catch(() => ({ data: { data: [] } })),
      getCustomerBookings(docId).catch(() => ({ bookings: [], links: [] })),
    ]).then(([detailsRes, notesRes, jobsRes, quotesRes, bookingsRes]) => {
      if (cancelled) return;
      setDetails(detailsRes.data);
      setNicknameValue(detailsRes.data?.nickname || '');
      setNotes(Array.isArray(notesRes.data) ? notesRes.data : []);
      setJobs(jobsRes.data?.jobs || []);
      setQuotations(quotesRes.data?.data || []);
      setBookings(bookingsRes.bookings);
      setBookingLinks(bookingsRes.links);
    }).catch(() => {}).finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [docId]);

  const copyLink = async (l: BookingLink) => {
    try { await Clipboard.setStringAsync(l.url); } catch { /* clipboard unavailable */ }
    const key = l.token || l.url;
    setCopiedToken(key);
    setTimeout(() => setCopiedToken((c) => (c === key ? null : c)), 2000);
  };

  const handleAddNote = async () => {
    if (!newNote.trim()) return;
    setAddingNote(true);
    try {
      const { data } = await api.post(`/users/${docId}/notes`, { text: newNote.trim() });
      setNotes((prev) => [data, ...prev]);
      setNewNote('');
    } catch { Alert.alert('ผิดพลาด'); }
    setAddingNote(false);
  };

  const handleDeleteNote = (noteId: string) => {
    Alert.alert('ลบบันทึก', 'ต้องการลบบันทึกนี้หรือไม่?', [
      { text: 'ยกเลิก', style: 'cancel' },
      { text: 'ลบ', style: 'destructive', onPress: async () => {
        await api.delete(`/users/notes/${noteId}`).catch(() => {});
        setNotes((prev) => prev.filter((n) => n.id !== noteId));
      }},
    ]);
  };

  const handleAddTag = async () => {
    if (!newTag.trim()) return;
    try {
      await api.post(`/users/${docId}/tags`, { name: newTag.trim() });
      const { data } = await api.get(`/users/${docId}/details`);
      setDetails(data);
      setNewTag('');
      setShowTagInput(false);
    } catch { Alert.alert('ผิดพลาด'); }
  };

  const handleRemoveTag = async (tagId: string) => {
    try {
      await api.delete(`/users/${docId}/tags/${tagId}`);
      setDetails((prev: any) => ({
        ...prev,
        tags: prev.tags.filter((t: any) => t.tag?.id !== tagId && t.id !== tagId),
      }));
    } catch {}
  };

  const saveNickname = async () => {
    try {
      await api.post(`/users/${docId}/nickname`, {
        nickname: nicknameValue.trim() || null,
      });
      setDetails((prev: any) => ({ ...prev, nickname: nicknameValue.trim() || null }));
      setEditingNickname(false);
      Alert.alert('สำเร็จ', 'บันทึกชื่อเรียกแล้ว');
    } catch {
      Alert.alert('ผิดพลาด', 'ไม่สามารถบันทึกได้');
    }
  };

  const isLine = channelType === 'line';
  const formatDate = (d: string) => {
    if (!d) return '-';
    return new Date(d).toLocaleDateString('th-TH', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
    });
  };

  if (loading) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#6366f1" />
      </View>
    );
  }

  const customer = details || {};
  const tags = customer.tags?.map((ct: any) => ct.tag) || [];
  const orders = customer.orders || [];

  return (
    <ScrollView
      style={styles.container}
      contentContainerStyle={{ paddingBottom: insets.bottom + 20 }}
    >
      {/* Profile header */}
      <View style={styles.profileHeader}>
        {pictureUrl ? (
          <Image source={{ uri: pictureUrl }} style={styles.avatar} cachePolicy="disk" transition={150} />
        ) : (
          <View style={[styles.avatar, styles.avatarPlaceholder]}>
            <Text style={styles.avatarText}>
              {displayName?.charAt(0)?.toUpperCase() || '?'}
            </Text>
          </View>
        )}
        <Text style={styles.name}>{customer.nickname || displayName || 'ไม่ทราบชื่อ'}</Text>
        {customer.nickname && (
          <Text style={styles.platformNameLabel}>({customer.displayName})</Text>
        )}

        {/* Nickname edit */}
        {editingNickname ? (
          <View style={styles.nicknameEditRow}>
            <TextInput
              style={styles.nicknameInput}
              value={nicknameValue}
              onChangeText={setNicknameValue}
              placeholder="ตั้งชื่อเรียก..."
              placeholderTextColor="#94a3b8"
              autoFocus
            />
            <TouchableOpacity style={styles.nicknameSaveBtn} onPress={saveNickname}>
              <Text style={styles.nicknameSaveBtnText}>บันทึก</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={() => setEditingNickname(false)}>
              <Text style={styles.nicknameCancelText}>ยกเลิก</Text>
            </TouchableOpacity>
          </View>
        ) : (
          <TouchableOpacity style={styles.nicknameEditBtn} onPress={() => setEditingNickname(true)}>
            <Text style={styles.nicknameEditBtnText}>
              {customer.nickname ? 'แก้ไขชื่อเรียก' : 'ตั้งชื่อเรียก'}
            </Text>
          </TouchableOpacity>
        )}

        <View style={styles.channelRow}>
          <View style={[styles.channelDot, { backgroundColor: isLine ? '#10b981' : '#3b82f6' }]} />
          <Text style={styles.channelText}>
            {channel?.replace('Line_', 'LINE ').replace('FB_', 'FB ').replace('fb_', 'FB ')}
          </Text>
        </View>
        <View style={[styles.statusBadge, {
          backgroundColor: customer.status === 'RESOLVED' ? '#dcfce7' : customer.status === 'FOLLOW_UP' ? '#fef3c7' : '#e0e7ff',
        }]}>
          <Text style={[styles.statusText, {
            color: customer.status === 'RESOLVED' ? '#166534' : customer.status === 'FOLLOW_UP' ? '#92400e' : '#3730a3',
          }]}>
            {customer.status === 'RESOLVED' ? 'เสร็จสิ้น' : customer.status === 'FOLLOW_UP' ? 'ติดตาม' : 'เปิด'}
          </Text>
        </View>
      </View>

      {/* Info section */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>ข้อมูลลูกค้า</Text>
        <InfoRow label="เบอร์โทร" value={customer.phoneNumber || '-'} />
        <InfoRow label="สถานะข้อความ" value={customer.statusMessage || '-'} />
        <InfoRow label="เข้ามาครั้งแรก" value={formatDate(customer.firstContactAt)} />
        <InfoRow label="ข้อความล่าสุด" value={formatDate(customer.lastMessageAt)} />
        {customer.assignedToName && (
          <InfoRow label="มอบหมายให้" value={customer.assignedToName} />
        )}
      </View>

      {/* Tags */}
      {tags.length > 0 && (
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>แท็ก</Text>
          <View style={styles.tagsContainer}>
            {tags.map((tag: any) => (
              <View key={tag.id} style={[styles.tag, { backgroundColor: tag.color + '20' }]}>
                <View style={[styles.tagDot, { backgroundColor: tag.color }]} />
                <Text style={[styles.tagText, { color: tag.color }]}>{tag.name}</Text>
              </View>
            ))}
          </View>
        </View>
      )}

      {/* Notes */}
      {notes.length > 0 && (
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>บันทึก ({notes.length})</Text>
          {notes.map((note: any) => (
            <View key={note.id} style={styles.noteCard}>
              <Text style={styles.noteText}>{note.content}</Text>
              <Text style={styles.noteDate}>
                {formatDate(note.createdAt)} {note.adminName && `โดย ${note.adminName}`}
              </Text>
            </View>
          ))}
        </View>
      )}

      {/* Orders */}
      {orders.length > 0 && (
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>ออเดอร์ ({orders.length})</Text>
          {orders.slice(0, 10).map((order: any) => (
            <View key={order.id} style={styles.orderCard}>
              <View style={styles.orderHeader}>
                <Text style={styles.orderRef}>#{order.orderNumber || order.refNumber || order.id.substring(0, 8)}</Text>
                <View style={[styles.orderStatusBadge, {
                  backgroundColor: order.status === 'COMPLETED' ? '#dcfce7' : order.status === 'CANCELLED' ? '#fef2f2' : '#fef3c7',
                }]}>
                  <Text style={[styles.orderStatusText, {
                    color: order.status === 'COMPLETED' ? '#166534' : order.status === 'CANCELLED' ? '#991b1b' : '#92400e',
                  }]}>
                    {order.status === 'COMPLETED' ? 'สำเร็จ' : order.status === 'CANCELLED' ? 'ยกเลิก' : order.status === 'PENDING' ? 'รอดำเนินการ' : order.status || '-'}
                  </Text>
                </View>
              </View>
              <Text style={styles.orderAmount}>
                {order.totalAmount ? `฿${Number(order.totalAmount).toLocaleString()}` : '-'}
              </Text>
              {/* Order items */}
              {order.items?.length > 0 && (
                <View style={styles.orderItems}>
                  {order.items.map((item: any, idx: number) => (
                    <Text key={idx} style={styles.orderItemText}>
                      • {item.name || item.productName} x{item.quantity} {item.price ? `฿${Number(item.price).toLocaleString()}` : ''}
                    </Text>
                  ))}
                </View>
              )}
              <Text style={styles.orderDate}>{formatDate(order.createdAt)}</Text>
            </View>
          ))}
        </View>
      )}

      {/* Payments */}
      {customer.payments?.length > 0 && (
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>การชำระเงิน ({customer.payments.length})</Text>
          {customer.payments.slice(0, 10).map((payment: any) => (
            <View key={payment.id} style={styles.orderCard}>
              <View style={styles.orderHeader}>
                <Text style={styles.orderRef}>
                  {payment.method === 'TRANSFER' ? '💳 โอนเงิน' : payment.method || 'ชำระเงิน'}
                </Text>
                <Text style={[styles.orderAmount, { color: payment.status === 'CONFIRMED' ? '#166534' : '#1e293b' }]}>
                  ฿{Number(payment.amount || 0).toLocaleString()}
                </Text>
              </View>
              {payment.slipUrl && (
                <TouchableOpacity onPress={() => Linking.openURL(payment.slipUrl)}>
                  <Image source={{ uri: payment.slipUrl }} style={styles.slipImage} contentFit="cover" cachePolicy="disk" />
                </TouchableOpacity>
              )}
              <Text style={styles.orderDate}>{formatDate(payment.createdAt)}</Text>
            </View>
          ))}
        </View>
      )}
      {/* Tags */}
      <View style={styles.section}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
          <Text style={styles.sectionTitle}>แท็ก</Text>
          <TouchableOpacity onPress={() => setShowTagInput(!showTagInput)}>
            <Text style={{ fontSize: 12, color: '#6366f1', fontWeight: '600' }}>{showTagInput ? '✕' : '+ เพิ่ม'}</Text>
          </TouchableOpacity>
        </View>
        {showTagInput && (
          <View style={{ flexDirection: 'row', gap: 8, marginBottom: 10 }}>
            <TextInput
              style={[styles.nicknameInput, { flex: 1 }]}
              value={newTag}
              onChangeText={setNewTag}
              placeholder="ชื่อแท็ก..."
              placeholderTextColor="#94a3b8"
              onSubmitEditing={handleAddTag}
            />
            <TouchableOpacity style={styles.nicknameSaveBtn} onPress={handleAddTag}>
              <Text style={styles.nicknameSaveBtnText}>เพิ่ม</Text>
            </TouchableOpacity>
          </View>
        )}
        <View style={styles.tagsContainer}>
          {tags.map((tag: any) => (
            <TouchableOpacity
              key={tag.id}
              style={[styles.tag, { backgroundColor: (tag.color || '#6366f1') + '20' }]}
              onLongPress={() => Alert.alert('ลบแท็ก', `ลบ "${tag.name}"?`, [
                { text: 'ยกเลิก', style: 'cancel' },
                { text: 'ลบ', style: 'destructive', onPress: () => handleRemoveTag(tag.id) },
              ])}
            >
              <View style={[styles.tagDot, { backgroundColor: tag.color || '#6366f1' }]} />
              <Text style={[styles.tagText, { color: tag.color || '#6366f1' }]}>{tag.name}</Text>
            </TouchableOpacity>
          ))}
          {tags.length === 0 && !showTagInput && <Text style={{ fontSize: 12, color: '#94a3b8' }}>ไม่มีแท็ก (กดค้างเพื่อลบ)</Text>}
        </View>
      </View>

      {/* Notes */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>บันทึก ({notes.length})</Text>
        <View style={{ flexDirection: 'row', gap: 8, marginBottom: 10 }}>
          <TextInput
            style={[styles.nicknameInput, { flex: 1 }]}
            value={newNote}
            onChangeText={setNewNote}
            placeholder="เพิ่มบันทึก..."
            placeholderTextColor="#94a3b8"
          />
          <TouchableOpacity
            style={[styles.nicknameSaveBtn, addingNote && { opacity: 0.5 }]}
            onPress={handleAddNote}
            disabled={addingNote}
          >
            <Text style={styles.nicknameSaveBtnText}>บันทึก</Text>
          </TouchableOpacity>
        </View>
        {notes.map((note: any) => (
          <TouchableOpacity
            key={note.id}
            style={styles.noteCard}
            onLongPress={() => handleDeleteNote(note.id)}
          >
            <Text style={styles.noteText}>{note.text || note.content}</Text>
            <Text style={styles.noteDate}>
              {formatDate(note.createdAt)} {note.adminName || note.authorName ? `โดย ${note.adminName || note.authorName}` : ''}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* IRIS Jobs */}
      {jobs.length > 0 && (
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>งานที่จอง ({jobs.length})</Text>
          {jobs.map((job: any, idx: number) => (
            <View key={job.id || idx} style={styles.orderCard}>
              <Text style={{ fontSize: 13, fontWeight: '600', color: '#334155' }}>
                {job.job || job.detail || 'งานจัดเลี้ยง'}
              </Text>
              {job.due && <Text style={{ fontSize: 11, color: '#6366f1', fontWeight: '600', marginTop: 4 }}>📅 {job.due}</Text>}
              <View style={{ flexDirection: 'row', gap: 12, marginTop: 4 }}>
                {job.revenue && <Text style={{ fontSize: 11, color: '#64748b' }}>฿{Number(job.revenue).toLocaleString()}</Text>}
                {job.guest && <Text style={{ fontSize: 11, color: '#64748b' }}>👥 {job.guest} ท่าน</Text>}
                {job.city && <Text style={{ fontSize: 11, color: '#94a3b8' }}>📍 {job.city}</Text>}
              </View>
            </View>
          ))}
        </View>
      )}

      {/* Merit bookings (/booking page) */}
      <View style={styles.section}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
          <Text style={[styles.sectionTitle, { marginBottom: 0 }]}>การจองงานบุญ ({bookings.length})</Text>
          <TouchableOpacity onPress={() => setShowBookingLink(true)}>
            <Text style={{ fontSize: 12, color: '#6366f1', fontWeight: '600' }}>+ สร้างลิงก์จอง</Text>
          </TouchableOpacity>
        </View>
        {bookings.length === 0 ? (
          <Text style={{ fontSize: 12, color: '#94a3b8', marginBottom: bookingLinks.length ? 10 : 0 }}>
            ยังไม่มีการจอง — ส่งลิงก์จองให้ลูกค้าเพื่อผูกการจองกับแชตนี้
          </Text>
        ) : (
          bookings.map((b) => {
            const st = statusStyle(b.status);
            return (
              <View key={b.id} style={styles.orderCard}>
                <View style={styles.orderHeader}>
                  <Text style={styles.orderRef}>{b.code}</Text>
                  <View style={[styles.orderStatusBadge, { backgroundColor: st.bg }]}>
                    <Text style={[styles.orderStatusText, { color: st.fg }]}>{statusLabel(b.status)}</Text>
                  </View>
                </View>
                <Text style={{ fontSize: 12, color: '#64748b', marginTop: 4 }}>
                  {[
                    b.packageName,
                    b.eventDate,
                    b.floor,
                    b.source === 'chat_link' ? 'ผ่านลิงก์จอง' : null,
                    b.salesName ? `เซลล์ ${b.salesName}` : null,
                  ].filter(Boolean).join(' · ')}
                </Text>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: 4 }}>
                  <Text style={styles.orderAmount}>฿{Number(b.estimatedTotal || 0).toLocaleString()}</Text>
                  {b.quotationPublicUrl ? (
                    <TouchableOpacity onPress={() => Linking.openURL(b.quotationPublicUrl!)}>
                      <Text style={{ fontSize: 12, color: '#d97706', fontWeight: '600' }}>
                        📄 {b.quotationDocNo || 'ใบเสนอราคา'}
                        {b.quotationSendStatus === 'sent' ? ' ✓ ส่งในแชตแล้ว' : b.quotationSendStatus === 'failed' ? ' · ส่งในแชตไม่สำเร็จ' : ''}
                      </Text>
                    </TouchableOpacity>
                  ) : null}
                </View>
              </View>
            );
          })
        )}

        {bookingLinks.length > 0 && (
          <View style={{ marginTop: 6 }}>
            <Text style={{ fontSize: 12, fontWeight: '600', color: '#64748b', marginBottom: 6 }}>ลิงก์ที่ส่งให้ลูกค้า</Text>
            {bookingLinks.map((l) => {
              const key = l.token || l.url;
              return (
                <View key={key} style={[styles.orderCard, { flexDirection: 'row', alignItems: 'center', gap: 10 }]}>
                  <View style={{ flex: 1, minWidth: 0 }}>
                    <Text style={{ fontSize: 13, fontWeight: '600', color: '#334155' }} numberOfLines={1}>
                      {l.packageName || 'ให้ลูกค้าเลือกแพ็กเกจเอง'}
                      {l.estimatedTotal != null ? ` · ฿${Number(l.estimatedTotal).toLocaleString()}` : ''}
                    </Text>
                    <Text style={{ fontSize: 11, color: '#94a3b8', marginTop: 2 }}>
                      เปิด {l.openCount ?? 0} ครั้ง · จอง {l.bookingCount ?? 0} รายการ{l.createdByName ? ` · ${l.createdByName}` : ''}
                    </Text>
                  </View>
                  <TouchableOpacity onPress={() => copyLink(l)} style={{ paddingHorizontal: 10, paddingVertical: 6, borderRadius: 8, backgroundColor: '#eef2ff' }}>
                    <Text style={{ fontSize: 12, color: copiedToken === key ? '#059669' : '#4f46e5', fontWeight: '600' }}>
                      {copiedToken === key ? '✓ คัดลอกแล้ว' : 'คัดลอก'}
                    </Text>
                  </TouchableOpacity>
                </View>
              );
            })}
          </View>
        )}
      </View>

      <BookingLinkModal
        visible={showBookingLink}
        customer={{
          id: docId,
          oduserId: userId || customer.platformUserId || customer.oduserId || undefined,
          channel: customer.channel || channel || '',
          displayName: customer.nickname || displayName || '',
        }}
        onClose={() => { setShowBookingLink(false); refreshBookings(); }}
      />

      {/* Quotations (IRIS Quotation) — every document attributed to this chat, plus phone/name matches */}
      <View style={styles.section}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10, gap: 8 }}>
          <Text style={[styles.sectionTitle, { marginBottom: 0 }]}>
            ใบเสนอราคา{quotations.length > 0 ? ` (${quotations.length})` : ''}
          </Text>
          <View style={{ flexDirection: 'row', gap: 12 }}>
            <TouchableOpacity onPress={() => setShowAttachQuote(true)}>
              <Text style={{ fontSize: 12, color: '#64748b', fontWeight: '600' }}>ผูกใบที่มีอยู่</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={createGeneralQuotation} disabled={quoteBusy === 'create'}>
              <Text style={{ fontSize: 12, color: '#d97706', fontWeight: '600', opacity: quoteBusy === 'create' ? 0.5 : 1 }}>
                {quoteBusy === 'create' ? 'กำลังสร้าง…' : '+ สร้างใบเสนอราคาทั่วไป'}
              </Text>
            </TouchableOpacity>
          </View>
        </View>
        {quoteMsg ? (
          <Text style={{ fontSize: 11, marginBottom: 8, lineHeight: 16, color: quoteMsg.ok ? '#059669' : '#ef4444' }}>{quoteMsg.text}</Text>
        ) : null}
        {quotationsLoading ? (
          <ActivityIndicator color="#f59e0b" style={{ marginVertical: 8 }} />
        ) : quotations.length === 0 ? (
          <Text style={{ fontSize: 12, color: '#94a3b8' }}>
            ยังไม่มีใบเสนอราคา — งานบุญใช้ลิงก์จองด้านบน แพ็กเกจอื่นกด "สร้างใบเสนอราคาทั่วไป"
          </Text>
        ) : (
          quotations.map((q) => {
            const st = faStatusStyle(q.status);
            const origin = ORIGIN_STYLE[q.origin || ''] || ORIGIN_STYLE.manual;
            const busy = quoteBusy === q.docNo;
            return (
              <View key={q.docNo} style={[styles.orderCard, { backgroundColor: '#fffbeb' }]}>
                <View style={styles.orderHeader}>
                  <TouchableOpacity onPress={() => { if (q.editUrl) Linking.openURL(q.editUrl).catch(() => {}); }}>
                    <Text style={{ fontSize: 13, fontWeight: '700', color: '#d97706' }}>{q.docNo} ↗</Text>
                  </TouchableOpacity>
                  <View style={[styles.orderStatusBadge, { backgroundColor: st.bg }]}>
                    <Text style={[styles.orderStatusText, { color: st.fg }]}>{faStatusLabel(q.status)}</Text>
                  </View>
                </View>
                <Text style={{ fontSize: 12, color: '#475569', marginTop: 4 }}>{q.project || q.customer || '-'}</Text>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: 4 }}>
                  <Text style={{ fontSize: 11, color: '#94a3b8' }}>{q.date}</Text>
                  <Text style={{ fontSize: 12, fontWeight: '700', color: '#1e293b' }}>฿{Number(q.grandTotal || 0).toLocaleString('th-TH')}</Text>
                </View>
                <View style={{ flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: 6, marginTop: 6 }}>
                  <View style={{ paddingHorizontal: 8, paddingVertical: 2, borderRadius: 999, backgroundColor: origin.bg }}>
                    <Text style={{ fontSize: 10, fontWeight: '600', color: origin.fg }}>{originLabel(q)}</Text>
                  </View>
                  {q.crmSalesName || q.salesName ? (
                    <Text style={{ fontSize: 10, color: '#94a3b8' }}>👤 {q.crmSalesName || q.salesName}</Text>
                  ) : null}
                  {q.itemCount === 0 ? <Text style={{ fontSize: 10, color: '#f87171' }}>ยังไม่มีรายการ</Text> : null}
                </View>
                <View style={{ flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', gap: 14, marginTop: 8 }}>
                  <TouchableOpacity onPress={() => sendQuoteToChat(q.docNo)} disabled={busy || !q.attached}>
                    <Text style={{ fontSize: 12, fontWeight: '600', color: '#d97706', opacity: busy || !q.attached ? 0.4 : 1 }}>
                      📨 {busy ? 'กำลังส่ง…' : 'ส่งลิงก์เข้าแชต'}
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity onPress={() => copyQuoteLink(q)}>
                    <Text style={{ fontSize: 12, color: '#64748b', fontWeight: '600' }}>📋 คัดลอกลิงก์</Text>
                  </TouchableOpacity>
                  {!q.attached ? (
                    <TouchableOpacity onPress={() => attachQuote(q.docNo)} disabled={busy} style={{ marginLeft: 'auto' }}>
                      <Text style={{ fontSize: 12, fontWeight: '600', color: '#2563eb', opacity: busy ? 0.5 : 1 }}>ผูกกับแชตนี้</Text>
                    </TouchableOpacity>
                  ) : null}
                </View>
                {!q.attached ? (
                  <Text style={{ fontSize: 10, color: '#94a3b8', marginTop: 4 }}>ผูกกับแชตนี้ก่อนจึงส่งลิงก์เข้าแชตได้</Text>
                ) : null}
              </View>
            );
          })
        )}
      </View>

      <AttachQuotationModal
        visible={showAttachQuote}
        customer={{ id: docId, displayName: customer.nickname || displayName || 'ลูกค้า' }}
        onClose={() => setShowAttachQuote(false)}
        onAttached={(docNo) => {
          setShowAttachQuote(false);
          setQuoteMsg({ ok: true, text: `ผูก ${docNo} กับแชตนี้แล้ว` });
          reloadQuotations();
        }}
      />
    </ScrollView>
  );
}

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <View style={styles.infoRow}>
      <Text style={styles.infoLabel}>{label}</Text>
      <Text style={styles.infoValue}>{value}</Text>
    </View>
  );
}

